return { api_version=1,id="CS1_112",name="Holy Nova",text="Deal $2 damage to all enemy minions. Restore #2 Health to all friendly characters.",set="LEGACY",type="spell",class="priest",spell_school="holy",cost=3,on_play=function(ctx,self)local p=ctx:controller(self);cardlib.effects.damage_all(ctx, ctx:enemy_minions(self),2);local friends={ctx:player(p).hero};for _,e in ipairs(ctx:friendly_minions(self))do friends[#friends+1]=e end;cardlib.effects.heal_all(ctx, friends,2)end }
